import{_ as a}from"./chunks/04-turbo-modules-codegen.Hao7pXb0.js";import{_ as o,o as n,c as s,a2 as r}from"./chunks/framework.Dbgp30TS.js";const g=JSON.parse('{"title":"04 · TurboModules 与 Codegen：信使的新制服","description":"","frontmatter":{},"headers":[],"relativePath":"comics/04-turbo-modules-codegen.md","filePath":"comics/04-turbo-modules-codegen.md","lastUpdated":1794291790000}'),t={name:"comics/04-turbo-modules-codegen.md"};function c(d,e,l,i,p,u){return n(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="_04-·-turbomodules-与-codegen-信使的新制服" tabindex="-1">04 · TurboModules 与 Codegen：信使的新制服 <a class="header-anchor" href="#_04-·-turbomodules-与-codegen-信使的新制服" aria-label="Permalink to &quot;04 · TurboModules 与 Codegen：信使的新制服&quot;">​</a></h1><p><img src="'+a+`" alt="TurboModules 与 Codegen 流水线"></p><h2 id="一、-信使-是什么" tabindex="-1">一、&quot;信使&quot;是什么 <a class="header-anchor" href="#一、-信使-是什么" aria-label="Permalink to &quot;一、&quot;信使&quot;是什么&quot;">​</a></h2><p>第 03 章说过：JS 想调原生能力（相机、蓝牙、文件系统），需要一个&quot;信使&quot;。旧世界的信使（NativeModules）有两个毛病：</p><ol><li><strong>启动就全员上岗</strong>——100 多个模块在 App 启动时全部初始化，哪怕你只用 3 个；</li><li><strong>没有制服（类型）</strong>——JS 和原生各写一套&quot;口头约定&quot;，签名对不上只能运行时崩溃。</li></ol><p>TurboModules 的改革：<strong>懒上岗 + 穿制服</strong>。</p><h2 id="二、懒上岗-moduleholder-的证据" tabindex="-1">二、懒上岗：ModuleHolder 的证据 <a class="header-anchor" href="#二、懒上岗-moduleholder-的证据" aria-label="Permalink to &quot;二、懒上岗：ModuleHolder 的证据&quot;">​</a></h2><p>Android 侧的 [TurboModuleManager.kt:L26-L37](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/ReactAndroid/src/main/java/com/facebook/react/internal/turbomodule/core/TurboModuleManager.kt#L26-L37) 负责安装 JSI bindings，并实现&quot;从 Java 侧取模块&quot;的注册表接口。而实例的创建藏在 [ModuleHolder.kt:L22-L30](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/ReactAndroid/src/main/java/com/facebook/react/bridge/ModuleHolder.kt#L22-L30)：</p><blockquote><p>原生模块不是启动时全部创建——<strong>首次被 JS 调用时</strong>，才通过 provider 懒创建并初始化（<code>getOrCreateModule</code>，[TurboModuleManager.kt:L133-L175](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/ReactAndroid/src/main/java/com/facebook/react/internal/turbomodule/core/TurboModuleManager.kt#L133-L175)）。</p></blockquote><p>这就是 0.87 启动更快的第二块拼图（第一块是 index.js 的懒 getter）。</p><h2 id="三、穿制服-codegen-流水线" tabindex="-1">三、穿制服：Codegen 流水线 <a class="header-anchor" href="#三、穿制服-codegen-流水线" aria-label="Permalink to &quot;三、穿制服：Codegen 流水线&quot;">​</a></h2><p>Codegen（<code>@react-native/codegen@0.87.1</code>，与 RN 锁版本）是一条&quot;裁缝流水线&quot;：</p><h3 id="_3-1-第一步-你写-spec-规格书" tabindex="-1">3.1 第一步：你写 SPEC 规格书 <a class="header-anchor" href="#_3-1-第一步-你写-spec-规格书" aria-label="Permalink to &quot;3.1 第一步：你写 SPEC 规格书&quot;">​</a></h3><p>用 TypeScript/Flow 声明原生模块的接口——方法名、参数类型、返回类型。这份 SPEC 就是唯一事实来源。</p><h3 id="_3-2-第二步-解析成-schema" tabindex="-1">3.2 第二步：解析成 Schema <a class="header-anchor" href="#_3-2-第二步-解析成-schema" aria-label="Permalink to &quot;3.2 第二步：解析成 Schema&quot;">​</a></h3><p>Codegen 用 hermes-parser 把 SPEC 解析成统一的 Schema JSON。<code>codegen-0.87.1/lib/</code> 里的生成器全部以 Schema 为输入。</p><h3 id="_3-3-第三步-缝出三套制服" tabindex="-1">3.3 第三步：缝出三套制服 <a class="header-anchor" href="#_3-3-第三步-缝出三套制服" aria-label="Permalink to &quot;3.3 第三步：缝出三套制服&quot;">​</a></h3><p>以 [codegen-0.87.1/lib/generators/modules/GenerateModuleJniCpp.js:L12-L21](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/codegen-0.87.1/lib/generators/modules/GenerateModuleJniCpp.js#L12-L21) 为例：</p><blockquote><p>生成 <code>__hostFunction_*</code> 系列的 C++ JNI 桩代码，把 JSI 调用翻译成 <code>JavaTurboModule::invokeJavaMethod</code>，按方法签名精确分发到 Java 方法。</p></blockquote><p>同一份 Schema 还会生成 ObjC 协议、Java Spec 接口和 JS/TS 类型——<strong>四端签名永远一致</strong>，因为它们出自同一个源。</p><h2 id="四、完整调用链-串起来看" tabindex="-1">四、完整调用链（串起来看） <a class="header-anchor" href="#四、完整调用链-串起来看" aria-label="Permalink to &quot;四、完整调用链（串起来看）&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>JS: NativeStorage.getItem(&#39;k&#39;)</span></span>
<span class="line"><span> │  TurboModuleRegistry.get() → global.__turboModuleProxy(&#39;名字&#39;)   [同步进 C++]</span></span>
<span class="line"><span> ▼</span></span>
<span class="line"><span>C++: 生成的桩 __hostFunction_xxx(payload…)                          [类型已校验]</span></span>
<span class="line"><span> │  按 Schema 里的签名分发</span></span>
<span class="line"><span> ▼</span></span>
<span class="line"><span>平台层: JavaTurboModule.invokeJavaMethod(...)  /  ObjC 对应实现</span></span>
<span class="line"><span> ▼</span></span>
<span class="line"><span>你的原生代码执行，返回值沿原路同步/异步回到 JS</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>旧模块怎么办？0.87 留了兼容通道——[Libraries/BatchedBridge/NativeModules.js:L99-L166](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/Libraries/BatchedBridge/NativeModules.js#L99-L166) 里旧式包装依然存在：根据 method type 走 <code>BatchedBridge.enqueueNativeCall</code>（异步批量）或 <code>callNativeSyncHook</code>（同步钩子）。未迁移的第三方库<strong>能跑</strong>，但享受不到新架构红利。</p><h2 id="五、faq" tabindex="-1">五、FAQ <a class="header-anchor" href="#五、faq" aria-label="Permalink to &quot;五、FAQ&quot;">​</a></h2><p><strong>Q1：我自己写的原生模块会被自动加速吗？</strong> 不会被自动加速——必须提供 SPEC 并让 Codegen 接管（教程组件篇会实战一个自定义 TurboModule 的最小模板）。</p><p><strong>Q2：Codegen 什么时候跑？</strong> 构建期。Android 在 Gradle 生成任务里、iOS 在 Pod install 时的 React-Codegen pod 里，产物落盘到 build 目录，不污染你的源码。</p><p><strong>Q3：为什么 <code>@react-native/codegen</code> 是固定版本不写 <code>^</code>？</strong> 制服必须和身体完全贴合：生成的桩代码依赖 RN 内部 C++ 类的确切签名，版本漂移会直接编译失败。官方把它锁死是保护你。</p><hr><blockquote><p>下一章：<a href="./05-fabric">05 · Fabric</a>——新渲染引擎的一天：commit → diff → mount。</p></blockquote>`,29)])])}const m=o(t,[["render",c]]);export{g as __pageData,m as default};
